const fs = require("node:fs");

function readHandbook(inputPath) {
  return fs.readFileSync(inputPath, "utf8");
}

// Many headings in the archive appear multiple times with decoy/draft variants.
// Binding/structured data uses the canonical heading lines (no parenthetical).
// This extracts the section body for an exact heading line, selecting the last
// exact match to avoid earlier archived/draft threads.
function extractSection(markdown, headingLine) {
  const esc = headingLine.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const re = new RegExp(`^${esc}\\s*$`, "gmi");

  let match;
  let lastIndex = -1;
  while ((match = re.exec(markdown)) !== null) {
    lastIndex = match.index;
  }
  if (lastIndex < 0) return "";

  const afterHeading = markdown.indexOf("\n", lastIndex);
  const start = afterHeading >= 0 ? afterHeading + 1 : lastIndex;
  const rest = markdown.slice(start);
  const next = rest.search(/^##\s+/m);
  return next >= 0 ? rest.slice(0, next) : rest;
}

module.exports = { readHandbook, extractSection };
EOF
